    hidden_dim=1536,
    num_layers=22,
    num_heads=12,
    mlp_ratio=4.0,
    time_dim=256,
    xyz_fourier_bands=16,
    content_rope_base=10000.0,
    content_rope_fwd=1.0,
    content_rope_bits=10,
    content_rope_impl="continuous3d",
    aux_con_layer=16,
    use_flash_varlen=True,
    # Coordinates are already divided by each sample's shared norm_factor.
