    canonical_position_scale=1.0,
    canonical_xyz_mean=CANONICAL_XYZ_MEAN,
    canonical_xyz_std=CANONICAL_XYZ_STD,
    # Nonlinear flow-velocity head (v = stage1 - gt): 256-d xyz/time embedding
